lines=grid_s.splitlines(); lines[9]='6 6 5 5 5 6 6 6 6 5 6 6 6 6 6 5 6 5 6 6 6 6 6 6'; grid=[list(map(int,x.split())) for x in lines]; R,C=25,24
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v in (5,3,9) and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]==v and (nx,ny) not in seen:
      seen.add((nx,ny)); q.append((nx,ny))
   rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
   comps.append((v,len(comp),(min(rs),max(rs),min(cs),max(cs)),comp))
[(v,n,b) for v,n,b,_ in comps if v==5]
